        Long finishTimeMs,
        Long netFinishTimeMs,
        long penaltyMs,
        Long totalTimeMs,
        int checkpointCount,
        int coveredCheckpointCount,
        List<String> missingCheckpoints
) {

    /** 无中止事件场景的兼容构造器：净完赛耗时等于原始完赛耗时。 */
